import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.D0_YsCyK.js";const h=JSON.parse('{"title":"U1 复审：面板在线自升级后端全流程（只审不改）","description":"","frontmatter":{},"headers":[],"relativePath":"audit/U1-panel-upgrade-backend.md","filePath":"audit/U1-panel-upgrade-backend.md","lastUpdated":1792473847000}'),a={name:"audit/U1-panel-upgrade-backend.md"};function r(s,e,l,i,p,n){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="u1-复审-面板在线自升级后端全流程-只审不改" tabindex="-1">U1 复审：面板在线自升级后端全流程（只审不改） <a class="header-anchor" href="#u1-复审-面板在线自升级后端全流程-只审不改" aria-label="Permalink to &quot;U1 复审：面板在线自升级后端全流程（只审不改）&quot;">​</a></h1><ul><li>范围：<code>go-backend/internal/http/handler/system_upgrade.go</code>（824 行）为主，含 <code>secure_fetch.go</code>、<code>upgrade.go</code>（代理配置/版本工具）、<code>middleware/auth.go</code>、<code>.github/workflows/docker-build.yml</code> 资产命名、前端 <code>vite-frontend/src/api/index.ts</code> 调用面</li><li>背景配置：用户已开启 GitHub 加速代理，地址 <code>https://ghfast.top</code>（gh-proxy 风格）</li><li>方法：代码审计 + 常量推导 + 定向跑测（未真实请求外网）</li><li>总评：<strong>P0 0 / P1 0 / P2 3 / P3 4</strong>。核心下载链路无 agent 侧同类 bug；主要风险在「版本发现 API 经代理」单点、helper 无健康校验、异步阶段并发防护缺失、一组失效的回归测试。</li></ul><hr><h2 id="一、与-agent-侧同类-bug-的排查-重点项-结论-不存在" tabindex="-1">一、与 agent 侧同类 bug 的排查（重点项，结论：不存在） <a class="header-anchor" href="#一、与-agent-侧同类-bug-的排查-重点项-结论-不存在" aria-label="Permalink to &quot;一、与 agent 侧同类 bug 的排查（重点项，结论：不存在）&quot;">​</a></h2><p>agent 侧 bug 的本质是 <strong>CheckRedirect 域名白名单</strong>遗漏 <code>release-assets.githubusercontent.com</code>。面板侧下载走的是完全不同的机制：</p><ul><li><code>downloadReleaseAsset</code>（system_upgrade.go:574-599）经 <code>SecureFetch</code>（secure_fetch.go:219-280）下载，<strong>没有任何域名白名单</strong>：校验模型是「scheme 白名单 + 逐 IP 分级判定（元数据黑名单/私网 allowlist/公网强制 https）」，且 <code>CheckRedirect</code> 对每一跳重跑 <code>validateFetchURL</code>（secure_fetch.go:236-249）。</li><li>推导链：<code>https://github.com/…/releases/download/&lt;ver&gt;/docker-compose-v4.yml</code> → 302 → <code>https://release-assets.githubusercontent.com/…</code>（公网 IP + https）→ 逐跳校验通过。<strong>直连形态全程可行。</strong></li><li>代理形态：<code>buildSystemUpgradeDownloadURL</code>（:463-470）拼 <code>&lt;proxy&gt;/https://github.com/…</code>，与 gh-proxy 约定一致（与 install.sh 的 <code>maybe_proxy_url</code>、gh_mirror 同一模式，有测试形态断言 system_upgrade_test.go:70 的 wantURL）。SecureFetch 先校验代理域名 <code>ghfast.top</code>（公网 + https ✓）；gh-proxy 若服务端取回直出 200 则无跳转，若 302 到资产 CDN 则逐跳复检通过；上限 5 跳（secureFetchMaxRedirects）足够。</li><li>大小/超时匹配：被下载资产只有 compose 文件（数 KB）+ 其 <code>.sha256</code>（工作流 <code>docker-build.yml:404-409</code> 上传 <code>docker-compose-v4.yml</code>/<code>-v6.yml</code> 及同名 <code>.sha256</code>，与 <code>selectComposeAsset</code>（:287-292）的返回值一致）；<code>secureFetchMaxBody=50MB</code>、<code>secureFetchTotalTimeout=60s</code> 对慢代理绰绰有余；两段下载共用一个 60s ctx（:577），compose+sha 都是小文件，无挤占问题。</li><li>sha256 强校验 fail-closed（:588-598）：校验文件下载失败/为空/不匹配一律中止；工作流生成的 <code>.sha256</code> 为纯哈希（<code>awk &#39;{print $1}&#39;</code>）或 <code>hash filename</code> 两种形态，代码 <code>Split(&quot; &quot;)[0]</code> 均可解析。</li></ul><hr><h2 id="二、已修项复核-逐个在位-✅" tabindex="-1">二、已修项复核（逐个在位 ✅） <a class="header-anchor" href="#二、已修项复核-逐个在位-✅" aria-label="Permalink to &quot;二、已修项复核（逐个在位 ✅）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>证据</th></tr></thead><tbody><tr><td>G-001 version 字符集</td><td><code>validateUpgradeVersion</code>（:218-234）逐字符校验 <code>[0-9A-Za-z.\\-_]</code>，拼 URL（:510 区）与写 .env（:712 区）之前已收紧；与 <code>updateEnvVersion</code> 内二次校验（:378）形成纵深</td></tr><tr><td>O9-001 拒绝降级</td><td>systemUpgrade :755-763：<code>compareVersions(version, currentVer) &lt; 0</code> 时拒绝并 <code>log.Printf</code> 记录；同版本仅记录不拦截</td></tr><tr><td>O9-002 helper 回滚</td><td>helperScript（:294-350）<code>rollback()</code> 覆盖 pull 失败、up 失败两分支，成功才删 <code>.bak</code>；Go 侧 <code>replaceCompose</code>/<code>updateEnvVersion</code>/<code>startHelper</code> 失败均调 <code>restoreUpgradeBackups</code>（:803-824）</td></tr><tr><td>O9-003 下载前校验</td><td>systemUpgrade :745-748 注释明示且代码在位，位于 <code>downloadReleaseAsset</code>（:777）之前</td></tr><tr><td>O9-004 语义版本比较</td><td><code>systemUpgradeVersionResponse</code>（:644）与 <code>systemCheckUpdates</code>（:711 区）两处均为 <code>compareVersions(latest, current) &gt; 0</code>，<code>1.0.10 &gt; 1.0.9</code> 推导正确</td></tr></tbody></table><p>其他验证通过项：</p><ul><li><strong>入口与鉴权</strong>：<code>/api/v1/system/version|check-updates|upgrade</code> 注册于 handler.go:204-206；<code>middleware/auth.go:154</code> 对 <code>/api/v1/system/</code> 前缀统一 <code>requiresAdmin=true</code>；写代理配置的 <code>/api/v1/config/update(-single)</code> 同样在 requiresAdmin 名单内——无越权改代理/触发升级路径。</li><li><strong>并发（同步段）</strong>：<code>systemUpgradeMu.TryLock</code>（:721），二次请求返回「已有面板升级任务执行中」；<code>TestSystemUpgradeRejectsConcurrentRequests</code> 实测通过。</li><li><strong>currentPanelVersion</strong>：读 <code>FLUX_VERSION</code> 环境变量（:162-168），与 compose 资产 <code>FLUX_VERSION: ${FLUX_VERSION:-dev}</code>、镜像 tag <code>${FLUX_VERSION}</code> 的注入方式一致；缺失时为 <code>dev</code>，<code>compareVersions</code> 对 dev 的处理（视为最低）使检查更新/升级不被卡死。</li><li><strong>channel 解析</strong>：<code>normalizeReleaseChannel</code> 非 dev 一律 stable；<code>releaseChannelFromTag</code> 以 <code>^\\d+(\\.\\d+)+$</code> 判 stable、含 alpha/beta/rc 判 dev（upgrade.go:56-76）；纯数字 tag（如 <code>1.0.10</code>）归类正确。</li><li><strong>capability 前置检查</strong>（:241-285）：docker CLI/socket/compose/.env/后端镜像逐项检查且失败原因（含旧挂载丢失的修复指引）随响应返回，升级在 <code>capability.Capable=false</code> 时于落盘前拒绝。</li><li><strong>失败点落盘顺序</strong>：下载 → 备份 compose → 备份 .env → 替换 compose → 改 .env → 起 helper；任一步失败都在「容器被动重启之前」，且已改文件有 restore 兜底。</li><li><strong>错误信息</strong>（同步段）：均为可定位的中文错误（下载失败带文件名与底层错误、校验失败带期望/实际哈希、能力不足带逐项原因），未发现吞错；与本节 P2/P3 的问题集中在异步段与 API 段。</li></ul><p>定向跑测（本沙箱）：<code>TestSystemUpgrade*</code>、<code>TestSelectCompose*</code>、<code>TestUpdateEnvVersion*</code>、<code>TestBuildHelperRunArgs*</code>、<code>TestUpgradeBackup*</code> 等全部通过；例外见 U1-004。</p><hr><h2 id="三、新发现问题" tabindex="-1">三、新发现问题 <a class="header-anchor" href="#三、新发现问题" aria-label="Permalink to &quot;三、新发现问题&quot;">​</a></h2><h3 id="u1-001-p2-版本发现-api-经代理是单点故障-无直连降级" tabindex="-1">U1-001（P2）：版本发现 API 经代理是单点故障，无直连降级 <a class="header-anchor" href="#u1-001-p2-版本发现-api-经代理是单点故障-无直连降级" aria-label="Permalink to &quot;U1-001（P2）：版本发现 API 经代理是单点故障，无直连降级&quot;">​</a></h3><ul><li>证据：<code>fetchSystemUpgradeReleases</code>（system_upgrade.go:472-500）在代理开启时把 API 地址也拼上代理前缀：<code>https://ghfast.top/https://api.github.com/repos/iiiiiiiii7125-art/flvx-max/releases?per_page=50</code>；全链路无 fallback。</li><li>触发条件：代理开启 且 该 gh-proxy 实现不转发 <code>api.github.com</code>（gh-proxy 类服务对主站/资产域名的支持普遍，对 api 子域的支持因实现而异，无法从代码判定 ghfast.top 的行为）。</li><li>影响：<code>/system/version</code> 返回 Reason 报错、左下角更新徽标失效；<code>/system/check-updates</code> 直接 -2 失败，前端版本列表为空、无从选版；无显式 version 的 <code>/system/upgrade</code> 同样失败。<strong>资产下载链路本身不受影响</strong>——显式带 version 的升级请求完全绕过 API（:738-746 仅在 version 为空时才调用 resolve），故此项不阻断「已知版本号」的升级，只阻断「发现新版本」。</li><li>附带差异（与 SecureFetch 对比）：该路径用裸 <code>http.Client</code>（:478）+ <code>systemUpgradeHTTPGet</code>，无 SSRF 分级校验（URL 由常量+管理员代理配置构成、无用户输入，风险可控）、无 User-Agent（靠 Go 默认 UA，GitHub 接受）、<code>json.NewDecoder(resp.Body).Decode</code> 无大小上限、15s 超时经慢代理拉 50 条 release 时可能偏紧（见 U1-006）。</li></ul><h3 id="u1-002-p2-helper-以「up-命令返回-0」为成功标准-无新版本健康校验-且成功即删备份" tabindex="-1">U1-002（P2）：helper 以「up 命令返回 0」为成功标准，无新版本健康校验，且成功即删备份 <a class="header-anchor" href="#u1-002-p2-helper-以「up-命令返回-0」为成功标准-无新版本健康校验-且成功即删备份" aria-label="Permalink to &quot;U1-002（P2）：helper 以「up 命令返回 0」为成功标准，无新版本健康校验，且成功即删备份&quot;">​</a></h3><ul><li>证据：helperScript（:294-350）：<code>docker compose up -d --force-recreate</code> 成功后直接 <code>log &quot;升级完成&quot;</code> 并 <code>rm -f docker-compose.yml.upgrade.bak .env.upgrade.bak</code>。</li><li>触发条件：新镜像能被 compose 拉起但进程本身起不来/立崩（镜像内容损坏、DB 迁移失败、与旧 .env 不兼容等）。<code>up -d</code> 对「容器已创建」即返回 0，不等待进程健康。</li><li>影响：面板进入 crash-loop 宕机，自动回滚不触发（O9-002 的 rollback 只覆盖 pull 失败与 up 命令本身失败），且 <code>.bak</code> 已被删除，恢复只能靠人工 SSH + 旧镜像 tag 手工处理。同时全程无状态查询接口（见 U1-007），前端只能靠轮询 <code>/system/version</code> 猜结果。</li></ul><h3 id="u1-003-p2-并发防护只覆盖同步段-helper-异步执行期间可二次发起升级" tabindex="-1">U1-003（P2）：并发防护只覆盖同步段，helper 异步执行期间可二次发起升级 <a class="header-anchor" href="#u1-003-p2-并发防护只覆盖同步段-helper-异步执行期间可二次发起升级" aria-label="Permalink to &quot;U1-003（P2）：并发防护只覆盖同步段，helper 异步执行期间可二次发起升级&quot;">​</a></h3><ul><li>证据：<code>systemUpgradeMu</code> 在 handler 返回时 <code>defer Unlock</code>（:721-725），而 helper 是 <code>docker run -d</code> 脱离进程（startHelper :558-572），拉镜像/重建可持续数分钟；系统内无「升级进行中」的持久标记或状态接口。</li><li>触发条件：管理员在第一次升级的 helper 尚在运行时再次调用 <code>/system/upgrade</code>（前端按钮在首次请求返回后即恢复可用）。</li><li>影响链：第二次调用重新 <code>backupFile</code> → <strong><code>.bak</code> 被覆盖为第一次升级已替换后的 compose/.env，原始版本备份被污染</strong>，此后任一侧 rollback 恢复的都是中间态；两个 helper 先后/同时对同一 compose 项目执行 pull/up 互相干扰；helper 名为秒级时间戳（:818），同秒撞名还会让第二次 <code>docker run</code> 直接失败（该分支会触发 restore，把第一次的成果回滚掉）。</li></ul><h3 id="u1-004-p2-downloadreleaseasset-的两个回归测试自-d16-起失效-断言的-1mb-上限在生产代码中不存在" tabindex="-1">U1-004（P2）：downloadReleaseAsset 的两个回归测试自 D16 起失效，断言的 1MB 上限在生产代码中不存在 <a class="header-anchor" href="#u1-004-p2-downloadreleaseasset-的两个回归测试自-d16-起失效-断言的-1mb-上限在生产代码中不存在" aria-label="Permalink to &quot;U1-004（P2）：downloadReleaseAsset 的两个回归测试自 D16 起失效，断言的 1MB 上限在生产代码中不存在&quot;">​</a></h3><ul><li>证据： <ul><li><code>system_upgrade_test.go:28</code> <code>TestDownloadReleaseAssetUsesGithubProxyWhenEnabled</code> 与 <code>:75</code> <code>TestDownloadReleaseAssetRejectsOversizedBody</code> 均 stub <code>systemUpgradeHTTPGet</code> 并据此断言（前者断言最终 URL 形态，后者断言超 <code>maxSystemUpgradeComposeAssetBytes</code>(1MB) 时报「过大」）。</li><li>但 <code>systemUpgradeHTTPGet</code> 在生产代码中仅被 <code>fetchSystemUpgradeReleases</code>（:483）使用；<code>downloadReleaseAsset</code> 自提交 <code>dbeae5a</code>（R5-B5 D16）起改走 <code>SecureFetch</code>，从未调用该 stub；<code>maxSystemUpgradeComposeAssetBytes</code> 全仓仅被该测试引用，生产无任何 1MB 检查，「过大」错误串在该路径不存在。</li><li>实测（本沙箱）：两测试均 FAIL，表面原因是沙箱 DNS 拦截的 TLS 报错；但即使在真实 DNS 环境，stub 永不命中、gotURL 恒为空、断言同样不可能通过——<code>.audit/known-baseline.md</code> 将其归为「TLS 环境」失败并不准确，实为测试与实现脱节。</li></ul></li><li>影响：① compose 资产实际上限是 SecureFetch 的 50MB 而非设计意图的 1MB（有 sha256 钉死，实际风险低）；② 升级资产的代理下载路径<strong>没有有效的回归覆盖</strong>，URL 拼接类回归无人拦截。</li></ul><h3 id="u1-005-p3-带-v-前缀的版本号被误判为降级" tabindex="-1">U1-005（P3）：带 <code>v</code> 前缀的版本号被误判为降级 <a class="header-anchor" href="#u1-005-p3-带-v-前缀的版本号被误判为降级" aria-label="Permalink to &quot;U1-005（P3）：带 `v` 前缀的版本号被误判为降级&quot;">​</a></h3><ul><li>证据：<code>validateUpgradeVersion</code>（:218-234）字符集允许字母，故 <code>v1.0.10</code> 可通过校验；但 systemUpgrade 的版本比较（:755）未做节点侧已有的 <code>strings.TrimPrefix(version, &quot;v&quot;)</code> 处理（对照 upgrade.go 的 nodeUpgrade），<code>compareVersions</code> 对段 <code>v1</code> 的 <code>Atoi</code> 失败按 0 计 → <code>v1.0.10</code> vs 当前 <code>1.0.9</code> 返回 -1 → 回复「目标版本低于当前版本，不允许降级」。</li><li>触发条件：管理员在自定义版本输入处手填 <code>v1.0.10</code>。官方 tag 为纯数字、版本列表给出的也是纯数字，正常流程不触发；且纵使绕过比较，该 tag 在 GitHub 上不存在，下载会 404。仅为错误信息误导 + 与节点侧行为不一致。</li></ul><h3 id="u1-006-p3-fetchsystemupgradereleases-的超时与体积防护偏弱" tabindex="-1">U1-006（P3）：fetchSystemUpgradeReleases 的超时与体积防护偏弱 <a class="header-anchor" href="#u1-006-p3-fetchsystemupgradereleases-的超时与体积防护偏弱" aria-label="Permalink to &quot;U1-006（P3）：fetchSystemUpgradeReleases 的超时与体积防护偏弱&quot;">​</a></h3><ul><li>证据：:478 客户端超时 15s（经代理多一跳 + 50 条 release 的 JSON 体积，慢代理下有超时风险，失败表现为「获取版本列表失败」）；:497-499 解码无 <code>LimitReader</code>，异常代理可返回超大 body。URL 无用户输入，风险等级低。</li></ul><h3 id="u1-007-p3-升级进度-结果无可查询通道" tabindex="-1">U1-007（P3）：升级进度/结果无可查询通道 <a class="header-anchor" href="#u1-007-p3-升级进度-结果无可查询通道" aria-label="Permalink to &quot;U1-007（P3）：升级进度/结果无可查询通道&quot;">​</a></h3><ul><li>证据：startHelper 成功后 handler 立即返回 <code>systemUpgradeRunData</code>（含一句固定文案），此后无任何状态端点；helper 的 <code>upgrade.log</code> 写在宿主机部署目录，前端不可读；后端被重建后进程内状态归零，无法回答「上次升级成功还是失败」。用户排障只能 SSH。这是 U1-002 的伴生项。</li></ul><h3 id="u1-008-p3-内网-http-代理与-securefetch-私网策略冲突且无说明" tabindex="-1">U1-008（P3）：内网/HTTP 代理与 SecureFetch 私网策略冲突且无说明 <a class="header-anchor" href="#u1-008-p3-内网-http-代理与-securefetch-私网策略冲突且无说明" aria-label="Permalink to &quot;U1-008（P3）：内网/HTTP 代理与 SecureFetch 私网策略冲突且无说明&quot;">​</a></h3><ul><li>证据：代理地址来自管理员配置（<code>getGithubProxyConfig</code>，upgrade.go:88-110，仅补 scheme 前缀、无形态校验）。若用户填内网代理（如 <code>http://192.168.x.x:8080</code> 或解析到内网的主机名），资产下载会在 <code>validateFetchIP</code>（secure_fetch.go:128-143）以 <code>private network not allowlisted</code> 被拒，除非部署时另设 <code>FLVX_FETCH_ALLOW_PRIVATE_NETWORKS=true</code>/<code>FLVX_FETCH_PRIVATE_ALLOWLIST</code>；UI 文案与报错均未提示这一前置条件。报错文本本身可定位，故仅 P3。用户当前填的 <code>ghfast.top</code> 为公网 https，不受影响。</li></ul><h3 id="u1-009-p3-updateenvversion-前缀匹配过宽" tabindex="-1">U1-009（P3）：updateEnvVersion 前缀匹配过宽 <a class="header-anchor" href="#u1-009-p3-updateenvversion-前缀匹配过宽" aria-label="Permalink to &quot;U1-009（P3）：updateEnvVersion 前缀匹配过宽&quot;">​</a></h3><ul><li>证据：:390 以 <code>strings.HasPrefix(line, &quot;FLUX_VERSION=&quot;)</code> 匹配，会连带命中 <code>FLUX_VERSION_EXTRA=</code> 等同前缀变量并改写其值。.env 常规内容下不存在此类变量，概率低、无现网影响。</li></ul><hr><h2 id="四、结论-两种配置下能否走通" tabindex="-1">四、结论：两种配置下能否走通 <a class="header-anchor" href="#四、结论-两种配置下能否走通" aria-label="Permalink to &quot;四、结论：两种配置下能否走通&quot;">​</a></h2><h3 id="代理关-直连" tabindex="-1">代理关（直连） <a class="header-anchor" href="#代理关-直连" aria-label="Permalink to &quot;代理关（直连）&quot;">​</a></h3><p>可走通，无阻断点：API 直连 <code>api.github.com</code>（15s 超时为唯一软肋，U1-006）→ 资产经 SecureFetch 直连 github.com 并逐跳跟到 release-assets（已推导可行）→ sha256 强校验 → 文件备份/替换（失败可恢复）→ helper pull/up。 注意：代码默认值是<strong>代理开</strong>（<code>defaultGithubProxyEnabled=true</code>、<code>defaultGithubProxyURL=https://gcode.hostcentral.cc</code>，upgrade.go:37-38；且 <code>getGithubProxyConfig</code> 语义为配置值 <code>!= &quot;false&quot;</code> 即启用），「关」需在设置中显式关闭开关。</p><h3 id="代理开-当前-ghfast-top" tabindex="-1">代理开（当前 ghfast.top） <a class="header-anchor" href="#代理开-当前-ghfast-top" aria-label="Permalink to &quot;代理开（当前 ghfast.top）&quot;">​</a></h3><ul><li><strong>资产下载段：可走通</strong>（URL 形态、SecureFetch 逐跳校验、大小、超时、sha 校验均已逐项推导/验证，无 agent 式域名白名单坑）。</li><li><strong>版本发现段：取决于 ghfast.top 是否转发 api.github.com（U1-001）</strong>——这是代理开配置下唯一的潜在阻断点，且代码无降级。若其支持（主流 gh-proxy 实现多为全 GitHub 系域名转发），全流程走通；若不支持，现象为检查更新报错/版本列表为空，但用已知版本号发起的升级不受影响。</li><li>两种配置共有：U1-002（新版本进程级失败无自动回滚、备份已删）、U1-003（异步窗口二次升级）为执行段残余风险，与代理无关。</li></ul><p>修复优先级建议：U1-001（API 失败时回退直连或给出明确报错）→ U1-003（落盘进行中标记/锁延伸到 helper 终态）→ U1-002（helper 增加健康探针后再删备份）→ U1-004（重写两个失效测试，恢复代理下载回归覆盖）。</p>',39)])])}const g=o(a,[["render",r]]);export{h as __pageData,g as default};
